import SwiftUI

struct ReservationDetailsView: View {
    let reservation: Reservation
    @State private var remind = false

    var body: some View {
        List {
            ReservationSummary(reservation: reservation)
            if reservation.isLegacy {
                StatusPill(key: badgeKey(for: reservation))
            }
            Toggle(String(localized: "temple.reservation.reminder.toggle", bundle: .module), isOn: $remind)
            Button(String(localized: "temple.reservation.cancel", bundle: .module), role: .destructive) {}
        }
        .navigationTitle(String(localized: "temple.reservation.title", bundle: .module))
    }

    private func badgeKey(for reservation: Reservation) -> String {
        "temple.reservation.\(reservation.badge)Badge"
    }
}

import UserNotifications

enum ReservationReminder {
    static func content(for reservation: Reservation) -> UNMutableNotificationContent {
        let content = UNMutableNotificationContent()
        let format = String(localized: "temple.reservation.reminder.body", bundle: .module)
        content.body = String(format: format, reservation.ordinanceName, reservation.templeName, 30)
        return content
    }
}

import SwiftUI

struct UpcomingReservationsFooter: View {
    var body: some View {
        NavigationLink(value: TempleRoute.pastReservations) {
            Label(String(localized: "temple.reservation.title", bundle: .module), systemImage: "clock.arrow.circlepath")
        }
    }
}

